const H = (st, px) => Math.round(px * st.hscale);
const tint = (pct, v = "primary") => `color-mix(in oklab,var(--${v}) ${pct}%,var(--surface))`;
const ink = (k, pct = 78) => `color-mix(in oklab,var(--${k}) ${pct}%,var(--text))`;
const track = "color-mix(in oklab,var(--muted) 15%,var(--surface))";
const sub = (t, fs = 11.5) => `<div class="muted" style="font-size:${fs}px">${t}</div>`;
const sb = (t, k) => `<span style="display:inline-flex;align-items:center;gap:5px;height:20px;padding:0 8px;border-radius:999px;font:600 11px var(--font-b);white-space:nowrap;background:color-mix(in oklab,var(--${k}) 14%,var(--surface));color:${ink(k)}">${t}</span>`;
const cb = (on, s = 16) => `<span style="flex:none;display:inline-grid;place-items:center;width:${s}px;height:${s}px;border-radius:4px;${on ? "background:var(--primary);color:var(--on-primary);border:1px solid var(--primary)" : "border:1.5px solid var(--border);background:var(--surface)"}">${on ? ic("check", s - 4) : ""}</span>`;
const chip = (t, on) => `<span style="flex:none;display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 12px;border-radius:999px;font-size:12.5px;font-weight:500;white-space:nowrap;${on ? "background:var(--primary);color:var(--on-primary);border:1px solid var(--primary)" : "border:1px solid var(--border);background:var(--surface)"}">${t}</span>`;
const seg = (items, on, h = 32, fs = 12.5) => `<div style="flex:none;display:inline-flex;border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;background:var(--surface)">${items.map((t, i) => `<span style="height:${h}px;padding:0 12px;display:flex;align-items:center;gap:6px;font-size:${fs}px;font-weight:500;white-space:nowrap;${i ? "border-left:1px solid var(--border);" : ""}${i === on ? "background:var(--primary);color:var(--on-primary)" : ""}">${t}</span>`).join("")}</div>`;
const tog = (on) => `<span role="switch" aria-checked="${on}" style="flex:none;width:34px;height:20px;border-radius:999px;position:relative;background:${on ? "var(--primary)" : track};border:1px solid ${on ? "var(--primary)" : "var(--border)"}"><span style="position:absolute;top:1px;left:${on ? 15 : 1}px;width:16px;height:16px;border-radius:50%;background:var(--surface);box-shadow:var(--shadow-sm)"></span></span>`;
const stepper = (v, h = 34) => `<span style="flex:none;display:inline-flex;align-items:center;border:1px solid var(--border);border-radius:var(--radius);height:${h}px;background:var(--surface)"><span style="width:32px;display:grid;place-items:center;color:var(--muted)">${ic("minus", 14)}</span><b class="num" style="min-width:30px;text-align:center;font-size:14px">${v}</b><span style="width:32px;display:grid;place-items:center;color:var(--muted)">${ic("plus", 14)}</span></span>`;
const bar = (pct, k = "primary", h = 6) => `<div style="height:${h}px;border-radius:${h}px;background:${track};overflow:hidden"><div style="height:100%;width:${Math.max(2, Math.min(100, pct)).toFixed(1)}%;border-radius:${h}px;background:var(--${k})"></div></div>`;
const iconTile = (n, s = 34, k = "primary") => `<span style="flex:none;width:${s}px;height:${s}px;border-radius:var(--radius);display:grid;place-items:center;background:${tint(13, k)};color:${ink(k, 80)}">${ic(n, Math.round(s * 0.5))}</span>`;
const av = (ini, s = 28, k = 0) => `<span style="flex:none;width:${s}px;height:${s}px;border-radius:50%;display:grid;place-items:center;font:600 ${Math.round(s * 0.38)}px var(--font-b);background:${tint(16 + (k % 3) * 7, k % 2 ? "accent" : "primary")};color:${ink(k % 2 ? "accent" : "primary", 72)}">${ini}</span>`;
const mtop = (left, title, subt, right = "") => `<div class="mtop"><span style="display:flex;width:24px">${left ? ic(left, 22) : ""}</span><div style="text-align:center;min-width:0"><b style="font-size:15px">${title}</b>${subt ? `<div class="muted" style="font-size:11.5px">${subt}</div>` : ""}</div><span style="display:flex;width:24px;justify-content:flex-end">${right}</span></div>`;
const cardMark = (w = 34) => { const h = Math.round(w * 0.64); return `<span style="flex:none;position:relative;width:${w}px;height:${h}px;border-radius:${Math.max(3, w / 11)}px;background:linear-gradient(135deg,color-mix(in oklab,var(--primary) 85%,var(--text)),color-mix(in oklab,var(--accent) 70%,var(--primary)));display:block"><span style="position:absolute;left:${w * 0.13}px;top:${h * 0.3}px;width:${w * 0.2}px;height:${h * 0.26}px;border-radius:2px;background:color-mix(in oklab,var(--on-primary) 55%,transparent)"></span></span>`; };
const initials = (n) => n.replace(/&/g, "").split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("");
const pick = (map) => (p, st, rnd) => (map[p.variant] || Object.values(map)[0])(p, st, rnd);
const linkT = (t, k = "primary") => `<span style="font-weight:600;color:${ink(k, 85)};white-space:nowrap">${t}</span>`;

