<td style="padding:7px 12px;border-bottom:1px solid var(--border)"><div style="display:flex;gap:10px;align-items:center">${av(initials(n), 28, i)}<div style="min-width:0"><div style="font-weight:600;line-height:1.3">${n}</div><div class="muted" style="font-size:11.5px;line-height:1.3">${e}</div></div></div></td>
